import { createProjectByCategory, ProjectCategory, projectStore } from "@droid/project-interface"
import { Log } from "@fanfanlo"
import { Button } from "@mui/material"
import { useRouter } from "next/router"
import { useState } from "react"
import { useTranslation } from "react-i18next"
import { ProjectCategorySelectDialog } from "./ProjectCategorySelectDialog"
import { actionScriptUtils } from "../../../iproject/actions/script/script-action/IActionScript.inft"
const fileLog = new Log(true, 'CreateProjectButton');
fileLog.pause = false;

export const CreateProjectButton = () => {
    const { t } = useTranslation("droid-project/project/ui/components/content")
    const router = useRouter()
    const [dialogOpen, setDialogOpen] = useState(false)

    fileLog.log(`[CreateProjectButton] 渲染, dialogOpen=${dialogOpen}`)

    const handleOpenDialog = () => {
        fileLog.log(`[CreateProjectButton] 打开类别选择对话框`)
        setDialogOpen(true)
    }

    const handleCloseDialog = () => {
        fileLog.log(`[CreateProjectButton] 关闭类别选择对话框`)
        setDialogOpen(false)
    }

    const handleSelectCategory = async (category: ProjectCategory) => {
        fileLog.log(`[CreateProjectButton] 用户选择类别: ${category}`)

        const project = createProjectByCategory(category)
        fileLog.log(`[CreateProjectButton] 创建 project, id=${project.id}, category=${project.category}`)

        // 如果是 ScriptRunner，添加一个 script action
        if (category === ProjectCategory.ScriptRunner) {
            fileLog.log(`[CreateProjectButton] ScriptRunner: 添加 script action`)
            const actionGroup = project.triggerActionGroup.list[0].actionGroup
            fileLog.log(`[CreateProjectButton] actionGroup.list.length before: ${actionGroup.list.length}`)
            const scriptAction = actionScriptUtils.createDefaultData()
            fileLog.log(`[CreateProjectButton] 创建 scriptAction:`, JSON.stringify(scriptAction))
            actionGroup.list.push(scriptAction)
            fileLog.log(`[CreateProjectButton] actionGroup.list.length after: ${actionGroup.list.length}`)
        }

        projectStore.addDraft(project)
        fileLog.log(`[CreateProjectButton] project 已添加到 draft store`)

        // 构建跳转路径
        let path = `/project-editor?id=${project.id}`

        // 如果是 QuickAction，添加 isNew 参数，用于在编辑器中判断是否需要跳转到 action-list
        if (category === ProjectCategory.QuickAction) {
            path += '&isNew=true'
            fileLog.log(`[CreateProjectButton] QuickAction: 添加 isNew 参数`)
        }

        fileLog.log(`[CreateProjectButton] 准备跳转到: ${path}`)

        await router.prefetch(path)
        router.push(path)

        setDialogOpen(false)
    }

    return (
        <span>
            <Button
                data-id={"create-project-button.b79975b3-cc10-4e3e-bc05-478a98c925b5"}
                data-typeof-create-project-id="create-project-btn-from-ui-components-create-project-button"
                id="typeof-create-project-id-create-project-btn-from-ui-components-create-project-button"
                onClick={handleOpenDialog}
            >
                {t('content.create')}
            </Button>

            <ProjectCategorySelectDialog
                open={dialogOpen}
                onClose={handleCloseDialog}
                onSelect={handleSelectCategory}
            />
        </span>
    )
}
